 20→/** Send an email via SendGrid v3 API */
 21→async function sendViaSendGrid(
 22→  apiKey: string,
 23→  from: { email: string; name: string },
 24→  to: string,
 25→  subject: string,
 26→  htmlContent: string
 27→): Promise<{ ok: boolean; status: number; body: string }> {
 28→  const res = await fetch("https://api.sendgrid.com/v3/mail/send", {
 29→    method: "POST",
 30→    headers: {
 31→      Authorization: `Bearer ${apiKey}`,
 32→      "Content-Type": "application/json",
 33→    },
 34→    body: JSON.stringify({
 35→      personalizations: [{ to: [{ email: to }] }],
 36→      from: { email: from.email, name: from.name },
 37→      subject,
 38→      content: [{ type: "text/html", value: htmlContent }],
 39→    }),
 40→  });
 41→
 42→  const body = res.ok ? "" : await res.text();
 43→  return { ok: res.ok, status: res.status, body };
 44→}
