 46→serve(async (req) => {
 47→  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
 48→
 49→  const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
 50→  const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
 51→  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
 52→
 53→  try {
 54→    const { to, template_key, variables } = (await req.json()) as SendEmailRequest;
 55→
 56→    if (!to || !template_key) {
 57→      return new Response(JSON.stringify({ error: "Missing 'to' or 'template_key'" }), {
 58→        status: 400,
 59→        headers: { ...corsHeaders, "Content-Type": "application/json" },
 60→      });
 61→    }
 62→
 63→    // Load platform config for SendGrid credentials
 64→    const { data: config, error: configError } = await supabase
 65→      .from("platform_config")
 66→      .select("sendgrid_api_key, email_from_address, email_from_name, outbound_email_enabled, email_notify_ranking_complete, email_notify_resume_received")
 67→      .limit(1)
 68→      .single();
 69→
 70→    if (configError) throw new Error(`Config error: ${configError.message}`);
 71→
 72→    if (!config?.outbound_email_enabled) {
 73→      return new Response(JSON.stringify({ error: "Outbound email is disabled", skipped: true }), {
 74→        status: 200,
 75→        headers: { ...corsHeaders, "Content-Type": "application/json" },
 76→      });
 77→    }
 78→
 79→    if (!config.sendgrid_api_key) {
 80→      return new Response(JSON.stringify({ error: "SendGrid API key not configured" }), {
 81→        status: 400,
 82→        headers: { ...corsHeaders, "Content-Type": "application/json" },
 83→      });
 84→    }
 85→
 86→    // Check per-template notification settings
 87→    if (template_key === "ranking_complete" && !config.email_notify_ranking_complete) {
 88→      return new Response(JSON.stringify({ skipped: true, reason: "Ranking complete notifications disabled" }), {
 89→        status: 200,
 90→        headers: { ...corsHeaders, "Content-Type": "application/json" },
 91→      });
 92→    }
 93→    if (template_key === "resume_received" && !config.email_notify_resume_received) {
 94→      return new Response(JSON.stringify({ skipped: true, reason: "Resume received notifications disabled" }), {
 95→        status: 200,
 96→        headers: { ...corsHeaders, "Content-Type": "application/json" },
 97→      });
 98→    }
 99→
100→    // Load template
101→    const { data: template, error: tplError } = await supabase
102→      .from("email_templates")
103→      .select("subject, body_html")
104→      .eq("template_key", template_key)
105→      .single();
106→
107→    if (tplError || !template) {
108→      return new Response(JSON.stringify({ error: `Template '${template_key}' not found` }), {
109→        status: 404,
110→        headers: { ...corsHeaders, "Content-Type": "application/json" },
111→      });
112→    }
113→
114→    // Render template with variables
115→    const subject = renderTemplate(template.subject, variables);
116→    const htmlContent = renderTemplate(template.body_html, variables);
117→
118→    // Send via SendGrid
119→    const result = await sendViaSendGrid(
120→      config.sendgrid_api_key,
121→      { email: config.email_from_address || "noreply@rankora.co", name: config.email_from_name || "Rankora" },
122→      to,
123→      subject,
124→      htmlContent
125→    );
126→
127→    if (!result.ok) {
128→      console.error("SendGrid error:", result.status, result.body);
129→      return new Response(JSON.stringify({ error: "SendGrid delivery failed", details: result.body }), {
130→        status: 502,
131→        headers: { ...corsHeaders, "Content-Type": "application/json" },
132→      });
133→    }
134→
135→    return new Response(JSON.stringify({ success: true }), {
136→      status: 200,
137→      headers: { ...corsHeaders, "Content-Type": "application/json" },
138→    });
139→  } catch (err: unknown) {
140→    console.error("send-email error:", err);
141→    return new Response(JSON.stringify({ error: err instanceof Error ? err.message : String(err) }), {
142→      status: 500,
143→      headers: { ...corsHeaders, "Content-Type": "application/json" },
144→    });
145→  }
146→});
