 24→      setTimeout(() => setCopied(false), 2000);
 25→    }
 26→  };
 27→
 28→  const handleToggleEmail = async (checked: boolean) => {
 29→    if (!user) return;
 30→    setTogglingEmail(true);
 31→    const { error } = await supabase
 32→      .from("profiles")
 33→      .update({ email_enabled: checked })
 34→      .eq("user_id", user.id);
 35→    if (error) {
