 85→            </p>
 86→          </>
 87→        ) : (
 88→          <div className="rounded-md bg-accent/50 px-3 py-3 text-sm text-muted-foreground text-center">
 89→            No inbox email assigned yet.
 90→          </div>
 91→        )}
 92→        <div className="flex items-center justify-between rounded-lg border border-border px-4 py-3">
 93→          <Label htmlFor="email-toggle" className="text-sm font-medium cursor-pointer">
 94→            Email ingestion enabled
 95→          </Label>
 96→          <Switch
 97→            id="email-toggle"
 98→            checked={profile?.email_enabled ?? true}
 99→            onCheckedChange={handleToggleEmail}
100→            disabled={togglingEmail}
101→          />
102→        </div>
103→
104→        {/* How it works */}
105→        <Collapsible open={howItWorksOpen} onOpenChange={setHowItWorksOpen}>
106→          <CollapsibleTrigger asChild>
107→            <Button variant="ghost" size="sm" className="w-full justify-between text-muted-foreground text-xs">
108→              <span className="flex items-center gap-1.5">
109→                <Info className="h-3.5 w-3.5" />
110→                How email ingestion works
111→              </span>
112→              <ChevronDown className={`h-3.5 w-3.5 transition-transform ${howItWorksOpen ? "rotate-180" : ""}`} />
113→            </Button>
114→          </CollapsibleTrigger>
115→          <CollapsibleContent className="pt-2">
