582→/** Inline template editor component */
583→function EmailTemplateEditor({
584→  template,
585→  onSave,
586→  saving,
587→}: {
588→  template: { id: string; template_key: string; subject: string; body_html: string; description: string | null };
589→  onSave: (subject: string, body_html: string) => void;
590→  saving: boolean;
591→}) {
592→  const [subject, setSubject] = useState(template.subject);
593→  const [bodyHtml, setBodyHtml] = useState(template.body_html);
594→  const dirty = subject !== template.subject || bodyHtml !== template.body_html;
595→
596→  const variableHints: Record<string, string[]> = {
597→    ranking_complete: ["user_name", "job_title", "resume_count", "job_id", "app_url"],
598→    resume_received: ["user_name", "job_title", "attachment_count", "filename", "job_id", "app_url"],
599→  };
600→
601→  const vars = variableHints[template.template_key] || [];
602→
603→  return (
604→    <Card>
605→      <CardHeader className="pb-3">
606→        <CardTitle className="text-lg flex items-center gap-2">
607→          <FileText className="h-5 w-5" />
608→          {template.template_key.replace(/_/g, " ").replace(/\b\w/g, (l) => l.toUpperCase())}
609→        </CardTitle>
610→        {template.description && (
611→          <CardDescription>{template.description}</CardDescription>
612→        )}
613→      </CardHeader>
614→      <CardContent className="space-y-4">
615→        {vars.length > 0 && (
616→          <div className="flex flex-wrap gap-1.5">
617→            <span className="text-xs text-muted-foreground">Variables:</span>
618→            {vars.map((v) => (
619→              <code key={v} className="text-xs bg-muted px-1.5 py-0.5 rounded">{`{{${v}}}`}</code>
620→            ))}
621→          </div>
622→        )}
623→        <div className="space-y-2">
624→          <Label className="text-sm font-medium">Subject</Label>
625→          <Input value={subject} onChange={(e) => setSubject(e.target.value)} />
626→        </div>
627→        <div className="space-y-2">
628→          <Label className="text-sm font-medium">Body (HTML)</Label>
629→          <Textarea
630→            value={bodyHtml}
631→            onChange={(e) => setBodyHtml(e.target.value)}
632→            className="font-mono text-xs min-h-[200px]"
633→          />
634→        </div>
635→        <Button
636→          onClick={() => onSave(subject, bodyHtml)}
637→          disabled={!dirty || saving}
638→          className="gap-2"
639→        >
640→          <Save className="h-4 w-4" />
641→          {saving ? "Saving..." : "Save Template"}
642→        </Button>
643→      </CardContent>
644→    </Card>
645→  );
646→}
